    [Fact]
    public async Task NestedComboIsRejectedBeforeItCanBecomeOrderIntent()
    {
        var tenant = await fixture.CreateTenantAsync(2, 1); var component = await CreateProduct(tenant.AccessToken, "simple", "Componente", null, false); var componentVariant = await CreateVariant(tenant.AccessToken, component, "Padrão", 5m); var inner = await CreateProduct(tenant.AccessToken, "combo", "Combo interno", null, false); await CreateVariant(tenant.AccessToken, inner, "Padrão", 0m); (await fixture.PutAsync($"api/v1/operations/catalog/products/{inner}/combo-configuration", new { pricingMode = "fixed_price", fixedPrice = 5m, groups = new[] { new { name = "Interno", minimumSelections = 1, maximumSelections = 1, displayOrder = 1, items = new[] { new { productId = component, productVariantId = (Guid?)componentVariant, additionalPrice = 0m, displayOrder = 1 } } } } }, tenant.AccessToken)).EnsureSuccessStatusCode(); var outer = await CreateProduct(tenant.AccessToken, "combo", "Combo externo", null, false); var outerVariant = await CreateVariant(tenant.AccessToken, outer, "Padrão", 0m); (await fixture.PutAsync($"api/v1/operations/catalog/products/{outer}/combo-configuration", new { pricingMode = "fixed_price", fixedPrice = 10m, groups = new[] { new { name = "Externo", minimumSelections = 1, maximumSelections = 1, displayOrder = 1, items = new[] { new { productId = inner, productVariantId = (Guid?)null, additionalPrice = 0m, displayOrder = 1 } } } } }, tenant.AccessToken)).EnsureSuccessStatusCode(); (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode(); Guid groupId, itemId; await using (var lookup = fixture.CreateDbContext()) { var comboId = await lookup.Set<Combo>().Where(x => x.ProductId == outer).Select(x => x.Id).SingleAsync(); groupId = await lookup.Set<ComboGroup>().Where(x => x.ComboId == comboId).Select(x => x.Id).SingleAsync(); itemId = await lookup.Set<ComboGroupItem>().Where(x => x.ComboGroupId == groupId).Select(x => x.Id).SingleAsync(); } var context = await Activate(tenant, outer, outerVariant); using var detail = await fixture.GetJsonAsync($"api/v1/table-device/menu/products/{outer}", context.DeviceToken); var version = detail.RootElement.GetProperty("configurationVersion").GetString()!; await using var stateDb = fixture.CreateDbContext(); var state = await stateDb.Set<CatalogState>().SingleAsync(x => x.EstablishmentId == tenant.EstablishmentId); var response = await fixture.PostAsync("api/v1/table-device/cart/simulate", new { sessionId = context.SessionId, localCartId = Guid.NewGuid(), catalogVersion = state.CatalogVersion, availabilityVersion = state.AvailabilityVersion, items = new[] { new { localCartItemId = Guid.NewGuid(), productId = outer, productVariantId = outerVariant, quantity = 1, configurationVersion = version, estimatedUnitAmount = 10m, configuration = new { combo = new { groups = new[] { new { groupId, selections = new[] { new { comboGroupItemId = itemId, quantity = 1 } } } } } } } } }, context.DeviceToken); response.EnsureSuccessStatusCode(); using var result = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); Assert.False(result.RootElement.GetProperty("canSubmit").GetBoolean()); Assert.Equal("NESTED_COMBO_NOT_ALLOWED", result.RootElement.GetProperty("issues")[0].GetProperty("errorCode").GetString()); Assert.Equal(0, await stateDb.Set<Order>().CountAsync(x => x.EstablishmentId == tenant.EstablishmentId));
    }

    [Fact]
    public async Task AcceptedReviewCannotAuthorizeAChangedAuthoritativeState()
    {
        var tenant = await fixture.CreateTenantAsync(2, 1); var product = await CreateProduct(tenant.AccessToken, "simple", "Review versionado", null, false); var variant = await CreateVariant(tenant.AccessToken, product, "Padrão", 10m); (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode(); var context = await Activate(tenant, product, variant); var simulationA = await PrepareSubmission(context, product, variant, new { }, 9m); var paused = fixture.OrderingHook.Pause("submission-before-locks"); var attempt = fixture.PostWithIdempotencyAsync("api/v1/table-device/orders", simulationA.Request, context.DeviceToken, simulationA.Key); await paused.Reached; await using (var db = fixture.CreateDbContext()) { var row = await db.Set<ProductVariant>().SingleAsync(x => x.Id == variant); row.BasePrice = 12m; row.Version++; await db.SaveChangesAsync(); } (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode(); paused.Release(); var stale = await attempt; Assert.Equal(HttpStatusCode.Conflict, stale.StatusCode); Assert.Equal("ORDER_REQUIRES_REVIEW", await fixture.ErrorCodeAsync(stale)); await AssertNoOrder(tenant.EstablishmentId, context.SessionId);
        var simulationB = await PrepareSubmission(context, product, variant, new { }, 10m); var confirmed = await fixture.PostWithIdempotencyAsync("api/v1/table-device/orders", simulationB.Request, context.DeviceToken, simulationB.Key); Assert.Equal(HttpStatusCode.Created, confirmed.StatusCode); await using var verify = fixture.CreateDbContext(); Assert.Equal(12m, (await verify.Set<Order>().SingleAsync(x => x.EstablishmentId == tenant.EstablishmentId)).TotalAmount); Assert.Equal(1, await verify.OutboxMessages.CountAsync(x => x.EstablishmentId == tenant.EstablishmentId && x.EventType == "order-submitted.v1"));
    }

    [Theory]
    [InlineData("product")]
    [InlineData("variant")]
    [InlineData("required-ingredient")]
    [InlineData("selected-additional")]
    public async Task MaterialAvailabilityChangeBeforeDefinitiveValidationLeavesNoCommercialEffect(string kind)
    {
        var tenant = await fixture.CreateTenantAsync(2, 1); var product = await CreateProduct(tenant.AccessToken, kind.Contains("ingredient", StringComparison.Ordinal) || kind.Contains("additional", StringComparison.Ordinal) ? "configurable" : "simple", "Item disponível", null, false); var variant = await CreateVariant(tenant.AccessToken, product, "Padrão", 10m); Guid ingredient = Guid.Empty; object configuration = new { }; decimal estimate = 10m;
        if (kind is "required-ingredient" or "selected-additional") { ingredient = await CreateIngredient(tenant.AccessToken, kind == "required-ingredient" ? "Base obrigatória" : "Adicional escolhido", 2m); var additional = kind == "selected-additional"; (await fixture.PutAsync($"api/v1/operations/catalog/products/{product}/ingredients", new { items = new[] { new { ingredientId = ingredient, includedByDefault = !additional, requiredForRecipe = !additional, canBeRemoved = false, canBeAdded = additional, maximumAdditionalQuantity = additional ? (decimal?)2m : null, additionalPrice = additional ? 2m : 0m, applicationScope = "whole_product" } } }, tenant.AccessToken)).EnsureSuccessStatusCode(); if (additional) { configuration = new { ingredients = new[] { new { ingredientId = ingredient, action = "add", quantity = 1m } } }; estimate = 12m; } }
        (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode(); var context = await Activate(tenant, product, variant); var prepared = await PrepareSubmission(context, product, variant, configuration, estimate); var paused = fixture.OrderingHook.Pause("submission-before-locks"); var submission = fixture.PostWithIdempotencyAsync("api/v1/table-device/orders", prepared.Request, context.DeviceToken, prepared.Key); await paused.Reached;
        var path = kind switch { "product" => $"products/{product}", "variant" => $"variants/{variant}", _ => $"ingredients/{ingredient}" }; (await fixture.PostAsync($"api/v1/operations/catalog/availability/{path}/change", new { available = false, reasonCode = "concurrent-test" }, tenant.AccessToken, true)).EnsureSuccessStatusCode(); paused.Release(); var response = await submission; Assert.Equal(HttpStatusCode.Conflict, response.StatusCode); var error = await fixture.ErrorCodeAsync(response); Assert.True(error is "PRODUCT_NOT_AVAILABLE" or "ORDER_REQUIRES_REVIEW", error); await AssertNoOrder(tenant.EstablishmentId, context.SessionId);
    }

