        var paused = fixture.OrderingHook.Pause("submission-before-locks"); var task = fixture.PostWithIdempotencyAsync("api/v1/table-device/orders", prepared.Request, context.DeviceToken, prepared.Key); await paused.Reached; await using (var db = fixture.CreateDbContext()) { var row = await db.Set<ProductVariant>().SingleAsync(x => x.Id == variant); row.BasePrice = 11m; row.Version++; await db.SaveChangesAsync(); } (await fixture.PostAsync("api/v1/operations/catalog/publish", null, materialTenant.AccessToken, true)).EnsureSuccessStatusCode(); paused.Release(); var rejected = await task; Assert.Equal(HttpStatusCode.Conflict, rejected.StatusCode); Assert.Equal("ORDER_REQUIRES_REVIEW", await fixture.ErrorCodeAsync(rejected)); await AssertNoOrder(materialTenant.EstablishmentId, context.SessionId);

