        var sizeResponse = await fixture.PostAsync("api/v1/operations/catalog/pizza-sizes", new { name = "Grande", shortName = "G", sliceCount = 8, diameterCm = 35m, displayOrder = 1 }, tenant.AccessToken); sizeResponse.EnsureSuccessStatusCode(); using var sizeJson = JsonDocument.Parse(await sizeResponse.Content.ReadAsStringAsync()); var size = sizeJson.RootElement.GetProperty("id").GetGuid();
        var doughResponse = await fixture.PostAsync("api/v1/operations/catalog/doughs", new { name = "Fina", description = "Fina", isDefault = true }, tenant.AccessToken); doughResponse.EnsureSuccessStatusCode(); using var doughJson = JsonDocument.Parse(await doughResponse.Content.ReadAsStringAsync()); var dough = doughJson.RootElement.GetProperty("id").GetGuid(); var crustResponse = await fixture.PostAsync("api/v1/operations/catalog/crusts", new { name = "Cheddar", description = "Cheddar", imageMediaId = (Guid?)null }, tenant.AccessToken); crustResponse.EnsureSuccessStatusCode(); using var crustJson = JsonDocument.Parse(await crustResponse.Content.ReadAsStringAsync()); var crust = crustJson.RootElement.GetProperty("id").GetGuid();
        var ingredient = await CreateIngredient(tenant.AccessToken, "Tomate seco", 2m); (await fixture.PutAsync($"api/v1/operations/catalog/products/{custom}/ingredients", new { items = new[] { new { ingredientId = ingredient, includedByDefault = false, requiredForRecipe = false, canBeRemoved = false, canBeAdded = true, maximumAdditionalQuantity = (decimal?)2m, additionalPrice = 2m, applicationScope = "fraction" } } }, tenant.AccessToken)).EnsureSuccessStatusCode();
        var flavor = Guid.NewGuid(); await using (var seed = fixture.CreateDbContext()) { var now = DateTimeOffset.UtcNow; seed.AddRange(new PizzaFlavor { Id = flavor, ProductId = flavorProduct, CreatedAt = now, UpdatedAt = now }, new PizzaFlavorPrice { Id = Guid.NewGuid(), PizzaFlavorId = flavor, PizzaSizeId = size, Price = 30m, CreatedAt = now, UpdatedAt = now }, new DoughSizePrice { DoughId = dough, PizzaSizeId = size, AdditionalPrice = 1m }, new CrustSizePrice { CrustId = crust, PizzaSizeId = size, AdditionalPrice = 2m }); await seed.SaveChangesAsync(); }
        (await fixture.PutAsync($"api/v1/operations/catalog/products/{custom}/pizza-configuration", new { sizes = new[] { new { pizzaSizeId = size, maximumFlavors = 4, displayOrder = 1, customBasePrice = (decimal?)40m, flavorPrice = (decimal?)null } }, doughIds = new[] { dough }, crustIds = new[] { crust } }, tenant.AccessToken)).EnsureSuccessStatusCode(); (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode();
        var context = await Activate(tenant, custom, variant); using var detail = await fixture.GetJsonAsync($"api/v1/table-device/menu/products/{custom}", context.DeviceToken); var version = detail.RootElement.GetProperty("configurationVersion").GetString()!; var configuration = new { ingredients = new[] { new { ingredientId = ingredient, action = "add", quantity = 1m } }, pizza = new { sizeId = size, doughId = dough, crustId = crust, fractions = new object[] { new { flavorId = flavor }, new { custom = new { ingredients = new[] { new { ingredientId = ingredient, quantity = 1m } } } } } } };
        var submitted = await SimulateAndSubmit(context, custom, variant, 1, version, 40m, configuration); await using var db = fixture.CreateDbContext(); var item = await db.Set<OrderItem>().SingleAsync(x => x.OrderId == submitted.OrderId); Assert.Equal(40m, item.UnitAmount); var fractions = await db.Set<OrderItemPizzaFraction>().Where(x => x.OrderItemId == item.Id).OrderBy(x => x.Position).ToListAsync(); Assert.Equal(30m, fractions[0].ReferenceAmount); Assert.Equal(40m, fractions[1].ReferenceAmount); Assert.True(fractions[1].IsCustom); Assert.Contains("Tomate seco", item.Snapshot); Assert.Single(await db.Set<OrderItemIngredient>().Where(x => x.OrderItemId == item.Id).ToListAsync()); var before = item.Snapshot; await MutateAndRepublish(tenant.AccessToken, custom); db.ChangeTracker.Clear(); Assert.Equal(before, (await db.Set<OrderItem>().SingleAsync(x => x.Id == item.Id)).Snapshot);
