    [Theory]
    [InlineData("fixed_price", 25, 29)]
    [InlineData("calculated", 0, 34)]
    public async Task ComboPersistsSelectionsAndUsesApprovedPricingStrategy(string strategy, decimal fixedPrice, decimal expected)
    {
        var tenant = await fixture.CreateTenantAsync(2, 1); var first = await CreateProduct(tenant.AccessToken, "simple", "Sanduíche", null, false); var firstVariant = await CreateVariant(tenant.AccessToken, first, "Grande", 20m); var second = await CreateProduct(tenant.AccessToken, "simple", "Suco", null, false); var secondVariant = await CreateVariant(tenant.AccessToken, second, "500ml", 10m); var combo = await CreateProduct(tenant.AccessToken, "combo", $"Combo {strategy}", "Combo histórico", true); var comboVariant = await CreateVariant(tenant.AccessToken, combo, "Padrão", 0m);
        (await fixture.PutAsync($"api/v1/operations/catalog/products/{combo}/combo-configuration", new { pricingMode = strategy, fixedPrice = strategy == "fixed_price" ? fixedPrice : (decimal?)null, groups = new object[] { new { name = "Principal", minimumSelections = 1, maximumSelections = 1, displayOrder = 1, items = new[] { new { productId = first, productVariantId = (Guid?)firstVariant, additionalPrice = 1m, displayOrder = 1 } } }, new { name = "Bebida", minimumSelections = 1, maximumSelections = 1, displayOrder = 2, items = new[] { new { productId = second, productVariantId = (Guid?)secondVariant, additionalPrice = 3m, displayOrder = 1 } } } } }, tenant.AccessToken)).EnsureSuccessStatusCode();
        (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode(); Guid[] groups; Guid[] selections; await using (var lookup = fixture.CreateDbContext()) { var comboId = await lookup.Set<Combo>().Where(x => x.ProductId == combo).Select(x => x.Id).SingleAsync(); groups = await lookup.Set<ComboGroup>().Where(x => x.ComboId == comboId).OrderBy(x => x.DisplayOrder).Select(x => x.Id).ToArrayAsync(); selections = new[] { await lookup.Set<ComboGroupItem>().Where(x => x.ComboGroupId == groups[0]).Select(x => x.Id).SingleAsync(), await lookup.Set<ComboGroupItem>().Where(x => x.ComboGroupId == groups[1]).Select(x => x.Id).SingleAsync() }; }
        var context = await Activate(tenant, combo, comboVariant); using var detail = await fixture.GetJsonAsync($"api/v1/table-device/menu/products/{combo}", context.DeviceToken); var version = detail.RootElement.GetProperty("configurationVersion").GetString()!; var configuration = new { combo = new { groups = new object[] { new { groupId = groups[0], selections = new[] { new { comboGroupItemId = selections[0], quantity = 1, configuration = new { variantId = firstVariant } } } }, new { groupId = groups[1], selections = new[] { new { comboGroupItemId = selections[1], quantity = 1, configuration = new { variantId = secondVariant } } } } } } };
        var submitted = await SimulateAndSubmit(context, combo, comboVariant, 1, version, expected, configuration); await using var db = fixture.CreateDbContext(); var item = await db.Set<OrderItem>().SingleAsync(x => x.OrderId == submitted.OrderId); Assert.Equal(expected, item.UnitAmount); var rows = await db.Set<OrderItemComboSelection>().Where(x => x.OrderItemId == item.Id).ToListAsync(); Assert.Equal(2, rows.Count); Assert.All(rows, x => Assert.NotNull(x.SelectedProductId)); Assert.Contains("Sanduíche", item.Snapshot); Assert.Contains("Suco", item.Snapshot); Assert.Equal(0, (await db.Set<Order>().SingleAsync(x => x.Id == submitted.OrderId)).DiscountAmount); var before = item.Snapshot; await MutateAndRepublish(tenant.AccessToken, combo); db.ChangeTracker.Clear(); Assert.Equal(before, (await db.Set<OrderItem>().SingleAsync(x => x.Id == item.Id)).Snapshot);
    }

