        await using var db = fixture.CreateDbContext(); var order = await db.Set<Order>().SingleAsync(x => x.Id == submitted.OrderId); var item = await db.Set<OrderItem>().SingleAsync(x => x.OrderId == order.Id); Assert.Equal(34.51m, item.UnitAmount); Assert.Equal(34.51m, order.TotalAmount);
