    [Fact]
    public async Task ConfigurableProductPersistsAuthoritativeRelationalAndJsonHistory()
    {
        var tenant = await fixture.CreateTenantAsync(2, 1);
        var productId = await CreateProduct(tenant.AccessToken, "configurable", "Hambúrguer Histórico", "Descrição original", true);
        var variantId = await CreateVariant(tenant.AccessToken, productId, "Duplo", 20m);
        var required = await CreateIngredient(tenant.AccessToken, "Carne", 0m);
        var removable = await CreateIngredient(tenant.AccessToken, "Cebola", 0m);
        var additional = await CreateIngredient(tenant.AccessToken, "Bacon", 2m);
        (await fixture.PutAsync($"api/v1/operations/catalog/products/{productId}/ingredients", new { items = new object[] { new { ingredientId = required, includedByDefault = true, requiredForRecipe = true, canBeRemoved = false, canBeAdded = false, maximumAdditionalQuantity = (decimal?)null, additionalPrice = 0m, applicationScope = "whole_product" }, new { ingredientId = removable, includedByDefault = true, requiredForRecipe = false, canBeRemoved = true, canBeAdded = false, maximumAdditionalQuantity = (decimal?)null, additionalPrice = 0m, applicationScope = "whole_product" }, new { ingredientId = additional, includedByDefault = false, requiredForRecipe = false, canBeRemoved = false, canBeAdded = true, maximumAdditionalQuantity = (decimal?)3m, additionalPrice = 2m, applicationScope = "whole_product" } } }, tenant.AccessToken)).EnsureSuccessStatusCode();
        var groupResponse = await fixture.PostAsync("api/v1/operations/catalog/customization-groups", new { name = "Molho", description = "Escolha quantitativa", selectionType = "quantity", minimumSelections = 0, maximumSelections = 3, displayType = "list", reusable = true, options = new[] { new { name = "Molho especial", description = "Molho histórico", additionalPrice = 3m, linkedIngredientId = (Guid?)null, linkedProductId = (Guid?)null, displayOrder = 1 } } }, tenant.AccessToken); groupResponse.EnsureSuccessStatusCode();
        using var groupJson = JsonDocument.Parse(await groupResponse.Content.ReadAsStringAsync()); var groupId = groupJson.RootElement.GetProperty("id").GetGuid(); Guid optionId; await using (var lookup = fixture.CreateDbContext()) optionId = await lookup.Set<CustomizationOption>().Where(x => x.CustomizationGroupId == groupId).Select(x => x.Id).SingleAsync();
        (await fixture.PutAsync($"api/v1/operations/catalog/products/{productId}/customization-groups", new { ids = new[] { groupId } }, tenant.AccessToken)).EnsureSuccessStatusCode();
        (await fixture.PostAsync("api/v1/operations/catalog/publish", null, tenant.AccessToken, true)).EnsureSuccessStatusCode();
        var context = await Activate(tenant, productId, variantId);
        using var detail = await fixture.GetJsonAsync($"api/v1/table-device/menu/products/{productId}", context.DeviceToken);
        var configurationVersion = detail.RootElement.GetProperty("configurationVersion").GetString()!;
        var configuration = new { selectedOptions = new[] { new { optionId, quantity = 2 } }, ingredients = new object[] { new { ingredientId = removable, action = "remove", quantity = 1m }, new { ingredientId = additional, action = "add", quantity = 2m } }, notes = new[] { "Bem passado" } };
        var submitted = await SimulateAndSubmit(context, productId, variantId, 2, configurationVersion, 30m, configuration);
        Assert.Equal(HttpStatusCode.Created, submitted.Response.StatusCode);

        await using var db = fixture.CreateDbContext();
        var order = await db.Set<Order>().SingleAsync(x => x.Id == submitted.OrderId); var item = await db.Set<OrderItem>().SingleAsync(x => x.OrderId == order.Id);
        Assert.Equal(60m, order.TotalAmount); Assert.Equal(30m, item.UnitAmount); Assert.Equal(60m, item.TotalAmount); Assert.Equal(2, item.Quantity); Assert.Equal(configurationVersion, item.ConfigurationVersion);
        var option = await db.Set<OrderItemOption>().SingleAsync(x => x.OrderItemId == item.Id); Assert.Equal("Molho especial", option.Name); Assert.Equal(2, option.Quantity); Assert.Equal(6m, option.AdditionalAmount);
        var ingredients = await db.Set<OrderItemIngredient>().Where(x => x.OrderItemId == item.Id).OrderBy(x => x.Action).ToListAsync(); Assert.Equal(2, ingredients.Count); Assert.Contains(ingredients, x => x.IngredientId == removable && x.Name == "Cebola" && x.Action == "remove" && x.AdditionalAmount == 0); Assert.Contains(ingredients, x => x.IngredientId == additional && x.Name == "Bacon" && x.Action == "add" && x.Quantity == 2 && x.AdditionalAmount == 4m);
        Assert.Equal("Bem passado", (await db.Set<OrderItemNote>().SingleAsync(x => x.OrderItemId == item.Id)).Note);
        using var snapshot = JsonDocument.Parse(item.Snapshot); var historical = snapshot.RootElement.GetProperty("Snapshot"); Assert.Equal("Hambúrguer Histórico", historical.GetProperty("product").GetProperty("Name").GetString()); Assert.Equal("Descrição original", historical.GetProperty("product").GetProperty("Description").GetString()); Assert.Equal("Duplo", historical.GetProperty("variant").GetProperty("Name").GetString()); Assert.Equal(30m, historical.GetProperty("pricing").GetProperty("unitAmount").GetDecimal()); Assert.Contains("Molho especial", item.Snapshot); Assert.Contains("Bacon", item.Snapshot); Assert.Contains("Cebola", item.Snapshot);
        var session = await db.Set<Appizza.Modules.Tables.TableSession>().SingleAsync(x => x.Id == context.SessionId); Assert.Equal(60m, session.TotalAmount); Assert.Equal(1, await db.OutboxMessages.CountAsync(x => x.EstablishmentId == tenant.EstablishmentId && x.EventType == "order-submitted.v1")); var before = item.Snapshot; await MutateAndRepublish(tenant.AccessToken, productId); db.ChangeTracker.Clear(); Assert.Equal(before, (await db.Set<OrderItem>().SingleAsync(x => x.Id == item.Id)).Snapshot);
    }

    private async Task<Guid> CreateProduct(string token, string type, string name, string? description, bool notes)
    { var response = await fixture.PostAsync("api/v1/operations/catalog/products", new { productType = type, name, description, internalCode = Guid.NewGuid().ToString("N"), primaryCategoryId = (Guid?)null, primaryImageMediaId = (Guid?)null, displayOrder = 1, requiresProduction = true, allowsNotes = notes, maximumNoteLength = notes ? 200 : (int?)null, preparationStationId = (Guid?)null }, token); response.EnsureSuccessStatusCode(); using var json = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); return json.RootElement.GetProperty("id").GetGuid(); }
    private async Task<Guid> CreateVariant(string token, Guid product, string name, decimal price)
    { var response = await fixture.PostAsync($"api/v1/operations/catalog/products/{product}/variants", new { name, internalCode = Guid.NewGuid().ToString("N"), basePrice = price, imageMediaId = (Guid?)null, displayOrder = 1 }, token); response.EnsureSuccessStatusCode(); using var json = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); return json.RootElement.GetProperty("id").GetGuid(); }
    private async Task<Guid> CreateIngredient(string token, string name, decimal price)
    { var response = await fixture.PostAsync("api/v1/operations/catalog/ingredients", new { name, kitchenName = name, description = $"{name} histórico", defaultAdditionalPrice = price, unitOfMeasure = "unit", imageMediaId = (Guid?)null }, token); response.EnsureSuccessStatusCode(); using var json = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); return json.RootElement.GetProperty("id").GetGuid(); }
    private async Task MutateAndRepublish(string token, Guid productId)
    { await using (var db = fixture.CreateDbContext()) { var product = await db.Set<Product>().SingleAsync(x => x.Id == productId); product.Name += " alterado"; product.Description = "Descrição posterior"; product.Status = "archived"; product.Version++; var variants = await db.Set<ProductVariant>().Where(x => x.ProductId == productId).ToListAsync(); foreach (var variant in variants) { variant.Name += " alterada"; variant.BasePrice += 7; variant.Version++; } var ingredients = await db.Set<Ingredient>().Where(x => x.EstablishmentId == product.EstablishmentId).ToListAsync(); foreach (var ingredient in ingredients) { ingredient.Name += " alterado"; ingredient.Version++; } var groupIds = await db.Set<CustomizationGroup>().Where(x => x.EstablishmentId == product.EstablishmentId).Select(x => x.Id).ToListAsync(); var options = await db.Set<CustomizationOption>().Where(x => groupIds.Contains(x.CustomizationGroupId)).ToListAsync(); foreach (var option in options) { option.Name += " alterada"; option.BaseAdditionalPrice += 1; option.Version++; } await db.SaveChangesAsync(); } (await fixture.PostAsync("api/v1/operations/catalog/publish", null, token, true)).EnsureSuccessStatusCode(); (await fixture.PostAsync($"api/v1/operations/catalog/availability/products/{productId}/change", new { available = false, reasonCode = "historical-test" }, token, true)).EnsureSuccessStatusCode(); }
    private async Task<OrderContext> Activate(dynamic tenant, Guid product, Guid variant)
    { var device = await fixture.RegisterAndBindAsync((string)tenant.AccessToken, (Guid)tenant.TableIds[0]); var session = await fixture.OpenSessionAsync(device.AccessToken); await using var db = fixture.CreateDbContext(); db.Add(new Station { Id = Guid.NewGuid(), EstablishmentId = (Guid)tenant.EstablishmentId, Name = "Cozinha Geral", IsDefault = true, CreatedAt = DateTimeOffset.UtcNow, UpdatedAt = DateTimeOffset.UtcNow }); await db.SaveChangesAsync(); return new((Guid)tenant.EstablishmentId, device.AccessToken, session, product, variant); }
    private async Task<Submitted> SimulateAndSubmit(OrderContext context, Guid product, Guid? variant, int quantity, string configurationVersion, decimal estimate, object configuration)
    {
        long catalogVersion, availabilityVersion; await using (var db = fixture.CreateDbContext()) { var state = await db.Set<CatalogState>().SingleAsync(x => x.EstablishmentId == context.EstablishmentId); catalogVersion = state.CatalogVersion; availabilityVersion = state.AvailabilityVersion; }
        var localCartId = Guid.NewGuid(); var simulationResponse = await fixture.PostAsync("api/v1/table-device/cart/simulate", new { sessionId = context.SessionId, localCartId, catalogVersion, availabilityVersion, items = new[] { new { localCartItemId = Guid.NewGuid(), productId = product, productVariantId = variant, quantity, configurationVersion, estimatedUnitAmount = estimate, configuration } } }, context.DeviceToken); simulationResponse.EnsureSuccessStatusCode(); var simulationText = await simulationResponse.Content.ReadAsStringAsync(); using var simulation = JsonDocument.Parse(simulationText); Assert.True(simulation.RootElement.GetProperty("canSubmit").GetBoolean(), simulationText);
        var key = Guid.NewGuid(); var response = await fixture.PostWithIdempotencyAsync("api/v1/table-device/orders", new { sessionId = context.SessionId, localCartId, clientSubmissionId = Guid.NewGuid(), simulationId = simulation.RootElement.GetProperty("simulationId").GetGuid(), simulationVersion = simulation.RootElement.GetProperty("simulationVersion").GetString(), acceptedReview = simulation.RootElement.GetProperty("requiresReview").GetBoolean() }, context.DeviceToken, key); var responseText = await response.Content.ReadAsStringAsync(); Assert.True(response.IsSuccessStatusCode, $"Submission failed ({response.StatusCode}): {responseText}"); using var payload = JsonDocument.Parse(responseText); return new(response, payload.RootElement.GetProperty("order").GetProperty("id").GetGuid());
    }
    private async Task<Prepared> PrepareSubmission(OrderContext context, Guid product, Guid variant, object configuration, decimal estimate)
    { using var detail = await fixture.GetJsonAsync($"api/v1/table-device/menu/products/{product}", context.DeviceToken); var version = detail.RootElement.GetProperty("configurationVersion").GetString()!; long catalogVersion, availabilityVersion; await using (var db = fixture.CreateDbContext()) { var state = await db.Set<CatalogState>().SingleAsync(x => x.EstablishmentId == context.EstablishmentId); catalogVersion = state.CatalogVersion; availabilityVersion = state.AvailabilityVersion; } var localCartId = Guid.NewGuid(); var response = await fixture.PostAsync("api/v1/table-device/cart/simulate", new { sessionId = context.SessionId, localCartId, catalogVersion, availabilityVersion, items = new[] { new { localCartItemId = Guid.NewGuid(), productId = product, productVariantId = variant, quantity = 1, configurationVersion = version, estimatedUnitAmount = estimate, configuration } } }, context.DeviceToken); response.EnsureSuccessStatusCode(); using var json = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); var request = new { sessionId = context.SessionId, localCartId, clientSubmissionId = Guid.NewGuid(), simulationId = json.RootElement.GetProperty("simulationId").GetGuid(), simulationVersion = json.RootElement.GetProperty("simulationVersion").GetString(), acceptedReview = json.RootElement.GetProperty("requiresReview").GetBoolean() }; return new(request, Guid.NewGuid()); }
    private async Task AssertNoOrder(Guid tenant, Guid sessionId) { await using var db = fixture.CreateDbContext(); Assert.Equal(0, await db.Set<Order>().CountAsync(x => x.EstablishmentId == tenant)); Assert.Equal(0, await db.Set<OrderItem>().CountAsync(x => x.OrderId == Guid.Empty)); Assert.Equal(0, await db.OutboxMessages.CountAsync(x => x.EstablishmentId == tenant && x.EventType == "order-submitted.v1")); Assert.Equal(0, (await db.Set<Appizza.Modules.Tables.TableSession>().SingleAsync(x => x.Id == sessionId)).TotalAmount); Assert.Equal(0, await db.IdempotencyRecords.CountAsync(x => x.EstablishmentId == tenant && x.OperationType == "ordering.submit" && x.ResponseStatus == 201)); }
    private sealed record OrderContext(Guid EstablishmentId, string DeviceToken, Guid SessionId, Guid ProductId, Guid VariantId);
    private sealed record Submitted(HttpResponseMessage Response, Guid OrderId);
    private sealed record Prepared(object Request, Guid Key);
